package com.fuelflex.platform.reception.entity;
import java.math.BigDecimal; import java.util.*; import com.fuelflex.platform.purchaseorder.entity.PurchaseOrderItem; import com.fuelflex.platform.product.entity.Product; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;
@Entity @Table(name="reception_items",uniqueConstraints=@UniqueConstraint(name="uk_reception_item_po_item",columnNames={"reception_id","purchase_order_item_id"})) @Getter @Setter @NoArgsConstructor
public class ReceptionItem { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="reception_id",nullable=false) private Reception reception; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="purchase_order_item_id",nullable=false) private PurchaseOrderItem purchaseOrderItem; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(name="ordered_quantity_snapshot",nullable=false,precision=19,scale=3) private BigDecimal orderedQuantitySnapshot; @Column(name="previously_received_quantity",nullable=false,precision=19,scale=3) private BigDecimal previouslyReceivedQuantity; @Column(name="backlog_before_reception",nullable=false,precision=19,scale=3) private BigDecimal backlogBeforeReception; @Column(name="received_quantity",nullable=false,precision=19,scale=3) private BigDecimal receivedQuantity; @Column(name="purchase_unit_price",precision=19,scale=4) private BigDecimal purchaseUnitPrice; @Column(length=3) private String currency; @Column(name="difference_quantity",nullable=false,precision=19,scale=3) private BigDecimal differenceQuantity; @Column(length=2000) private String observation; }
